YXRpYyBpbnQgbkluc3RyQ291bnQ9MDsKIAogICAgIHBvaW50ID0gKEludClhcmdzWzBdOwogCi0g
ICAgaWYgKCBCT1VORFMoIGFyZ3NbMF0sIENVUi56cDEubl9wb2ludHMgKSApCisgICAgaWYgKCBC
T1VORFMoIGFyZ3NbMF0sIENVUi56cDEubl9wb2ludHMgKQorICAgICAgfHwgQk9VTkRTKCBDVVIu
